#include <bits/stdc++.h>
using namespace std;

constexpr long long MOD = 1000000007;

long long power_mod(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

struct Combinations {
    vector<long long> fact;
    vector<long long> inv_fact;

    explicit Combinations(int maximum) : fact(maximum + 1, 1), inv_fact(maximum + 1, 1) {
        for (int value = 1; value <= maximum; ++value) {
            fact[value] = fact[value - 1] * value % MOD;
        }
        inv_fact[maximum] = power_mod(fact[maximum], MOD - 2);
        for (int value = maximum; value >= 1; --value) {
            inv_fact[value - 1] = inv_fact[value] * value % MOD;
        }
    }

    long long choose(int n, int selected) const {
        if (selected < 0 || selected > n) {
            return 0;
        }
        return fact[n] * inv_fact[selected] % MOD * inv_fact[n - selected] % MOD;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int maximum, q;
    cin >> maximum >> q;
    Combinations combinations(maximum);
    for (int query = 0; query < q; ++query) {
        int n, selected;
        cin >> n >> selected;
        cout << combinations.choose(n, selected) << '\n';
    }
}

